101	    void
102	    CHAOSLSQFwd::corrupt(uint8_t *data, unsigned size, Addr vaddr)
103	    {
104	        // Hot-path short-circuit: no injection configured.
105	        if (probability <= 0.0f) return;
106	        Cycles cur = cpu->curCycle();
107	        if (cur < first_clock) return;
108	        if (last_clock != Cycles(0) && cur > last_clock) return;
109	        if (max_faults != 0 && faults_injected_count >= max_faults) return;
110	
111	        // Bernoulli: does this forwarding event get corrupted?
112	        std::uniform_real_distribution<float> dist(0.0f, 1.0f);
113	        if (dist(rng) >= probability) return;
114	        if (size == 0) return;
115	
116	        // Choose byte to corrupt.
117	        int off = byte_offset;
118	        if (off < 0) {
119	            std::uniform_int_distribution<int> bdist(0, (int)size - 1);
120	            off = bdist(rng);
121	        }
122	        if (off >= (int)size) off = (int)size - 1;
123	
124	        int mask = fault_mask.any()
125	            ? (int)(fault_mask.to_ulong() & 0xff)
126	            : generateRandomMask(num_bits_to_change);
127	
128	        FaultType chosen = fault_type_enum;
129	        if (fault_type_enum == FaultType::Random) {
130	            int idx = random_fault_distribution(rng);
131	            chosen = static_cast<FaultType>(idx);
132	        }
133	
134	        switch (chosen) {
135	            case FaultType::StuckAtZero:
136	                data[off] &= ~(uint8_t)mask;
137	                stats->numStuckAtZero++;
138	                break;
139	            case FaultType::StuckAtOne:
140	                data[off] |= (uint8_t)mask;
141	                stats->numStuckAtOne++;
142	                break;
143	            case FaultType::BitFlip:
144	                data[off] ^= (uint8_t)mask;
145	                stats->numBitFlips++;
146	                break;
147	            default: break;
148	        }
149	        stats->numFaultsInjected++;
150	        ++faults_injected_count;
151	        writeLog(faultTypeToString(chosen), size, vaddr, off, mask);
152	        DPRINTF(LSQUnit, "CHAOSLSQFwd: corrupted forwarded byte %d (vaddr=%#x "
153	                "mask=%#x type=%s)\n", off, vaddr, mask,
154	                faultTypeToString(chosen));
155	    }
