            uint32_t v1 = input[i];                 /* 1st read */
            uint32_t bs = __builtin_bswap32(v1);    /* byte-swap (rev) — never feeds compare */
            swapped[i] = bs;                        /* store to DIFFERENT line */
            uint32_t v2 = __builtin_bswap32(bs);    /* folds to RELOAD of input[i] */
